import{bt as e,n as t,ot as n,st as r}from"./chunks/framework.CxhjsvYc.js";var i=JSON.parse(`{"title":"Search budget calibration","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/SEARCH-BUDGET-CALIBRATION.html"}],["meta",{"property":"og:title","content":"Search budget calibration | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/SEARCH-BUDGET-CALIBRATION.html"}],["meta",{"name":"twitter:title","content":"Search budget calibration | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/SEARCH-BUDGET-CALIBRATION.md","filePath":"audits/SEARCH-BUDGET-CALIBRATION.md","lastUpdated":1794227887000}`),a={name:`audits/SEARCH-BUDGET-CALIBRATION.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="search-budget-calibration" tabindex="-1">Search budget calibration <a class="header-anchor" href="#search-budget-calibration" aria-label="Permalink to “Search budget calibration”">​</a></h1><p><strong>Run:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42566748203" target="_blank" rel="noreferrer">GitHub Actions search-budget calibration #42566748203</a><br><strong>Branch:</strong> <code>audit/owner-feedback-followups</code><br><strong>Runner:</strong> GitHub-hosted Ubuntu, Node.js 22<br><strong>Date:</strong> 9 November 2026</p><h2 id="matrix" tabindex="-1">Matrix <a class="header-anchor" href="#matrix" aria-label="Permalink to “Matrix”">​</a></h2><p>The controlled matrix compared four expanded-state caps (5,000, 10,000, 20,000, unlimited) against three cooperative time budgets (15, 30, 60 seconds). Beam width and local branch limit were held at the browser defaults (256 and 128). All cases used the same deterministic inputs.</p><h3 id="harder-60-month-scenario" tabindex="-1">Harder 60-month scenario <a class="header-anchor" href="#harder-60-month-scenario" aria-label="Permalink to “Harder 60-month scenario”">​</a></h3><ul><li>Starting capital: LKR 1,000,000 across three accounts and three banks.</li><li>Horizon: 60 months.</li><li>Monthly inflow: LKR 10,000 into the first account.</li><li>Monthly strict outflow: LKR 5,000 from the first account.</li><li>AIT enabled; no compounding.</li><li>Search strategy: Absolute R+.</li></ul><table tabindex="0"><thead><tr><th style="text-align:right;">Time budget</th><th style="text-align:right;">Runtime range</th><th style="text-align:right;">Expanded states</th><th style="text-align:right;">Net interest after AIT</th><th style="text-align:right;">Final value after AIT</th><th style="text-align:right;">Bookings</th></tr></thead><tbody><tr><td style="text-align:right;">15 s</td><td style="text-align:right;">15.17–15.59 s</td><td style="text-align:right;">1,493–1,510</td><td style="text-align:right;">LKR 746,112.45</td><td style="text-align:right;">LKR 2,346,112.45</td><td style="text-align:right;">45</td></tr><tr><td style="text-align:right;">30 s</td><td style="text-align:right;">30.18–30.71 s</td><td style="text-align:right;">2,647–2,765</td><td style="text-align:right;">LKR 746,112.45</td><td style="text-align:right;">LKR 2,346,112.45</td><td style="text-align:right;">45</td></tr><tr><td style="text-align:right;">60 s</td><td style="text-align:right;">60.19–61.00 s</td><td style="text-align:right;">4,288–4,311</td><td style="text-align:right;">LKR 746,112.45</td><td style="text-align:right;">LKR 2,346,112.45</td><td style="text-align:right;">45</td></tr></tbody></table><p>All 12 combinations returned the same financial result, 45 bookings and LKR 285 transfer fees. The 5,000-state cap was not reached even in the longest run; therefore the 10,000, 20,000 and unlimited caps also did not bind. The 15/30/60-second time budgets did bind and increased explored states, but did not improve the selected financial result in this scenario.</p><p>Search remained bounded by beam/local pruning: approximately 62k–63k beam prunes and 43.7k local-combination prunes at 15 seconds; approximately 121k–126k and 74.4k–76.4k respectively at 30 seconds; approximately 250k–254k and 252k–260k at 60 seconds.</p><p><strong>Important:</strong> <code>optimality_proven</code> was false in every case. Identical results do not establish global optimality; they show only that the extra search budget did not improve the best candidate found under the fixed beam width/local branch limit.</p><h3 id="_24-month-baseline-control" tabindex="-1">24-month baseline control <a class="header-anchor" href="#_24-month-baseline-control" aria-label="Permalink to “24-month baseline control”">​</a></h3><p>A smaller 24-month, LKR 300,000, three-bank scenario without scheduled inflows/outflows was also run across the same 12 combinations:</p><ul><li>Runtime: 4.58–5.28 seconds.</li><li>Expanded states: 1,908.</li><li>Net interest after AIT: LKR 73,441.</li><li>Final value after AIT: LKR 373,441.</li><li>Transfer fees: LKR 105.</li><li>Bookings: 8.</li><li>All settings returned the same result; neither time nor state limits bound.</li></ul><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to “Recommendation”">​</a></h2><ol><li><strong>Keep the browser defaults at 10,000 expanded states / 30 seconds.</strong> The 10k cap is comfortably above the 4.3k states reached in the harder test, and 30 seconds provides headroom over the 15-second result without the doubled runtime of 60 seconds.</li><li><strong>Keep explicit unlimited/longer-running controls.</strong> A user running a more complex portfolio should be able to opt into a longer time budget and an uncapped state limit.</li><li><strong>Do not lower the state cap to 5,000 from this evidence alone.</strong> It did not bind in these scenarios, but the test matrix is not an exhaustive portfolio distribution.</li><li><strong>Do not increase the default time budget to 60 seconds.</strong> It doubled runtime without changing the candidate on the tested scenarios.</li><li><strong>For a quality improvement, benchmark beam width and local branch limit next.</strong> The pruning counts are much larger than the number of expanded states, so those controls may have more influence than simply raising the state cap.</li></ol><h2 id="limitations-and-follow-up" tabindex="-1">Limitations and follow-up <a class="header-anchor" href="#limitations-and-follow-up" aria-label="Permalink to “Limitations and follow-up”">​</a></h2><ul><li>Measurements are runner-specific; runtime values are not user-device performance guarantees.</li><li>The calibration uses one harder deterministic scenario plus one smaller control. Add varied account counts, bank counts, capital distributions, payout types and outflow policies before changing defaults.</li><li>The search does not prove optimality in these runs. The UI/report must continue to distinguish a valid result from an optimality proof.</li><li>The workflow uploaded the full 12-row JSON result as the artifact attached to the linked Actions run.</li></ul>`,17)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};